{
  "name": "Cytomat自动化微孔板培养存储系统",
  "name_en": "Cytomat Automated Microplate Incubator-Storage System",
  "manufacturer": "Thermo Fisher Scientific",
  "description": "该设备是实验室自动化流程中的微孔板培养与存储一体机，可在受控温度、CO2、O2和湿度条件下保存和培养板件，并通过内部机械传送机构在存储位、等待位、转运位和外部暴露位之间自动转移微孔板，支持条码读取与振荡培养。",
  "description_en": "This device is an automated microplate incubator and storage unit for laboratory workflows. It maintains controlled temperature, CO2, O2, and humidity conditions, and uses internal handling mechanics to move plates between storage, wait, transfer, and exposed positions. It also supports barcode reading and shaking incubation.",
  "tag_hints": [
    "automated incubator",
    "microplate storage hotel",
    "CO2/O2 humidity control",
    "robotic plate transfer",
    "integrated plate shaker",
    "barcode-based plate tracking"
  ],
  "actions": [
    {
      "action_name": "auto-action_exposed_to_storage",
      "description": "将外部暴露位的微孔板送回存储位。",
      "description_en": "Move a microplate from the exposed external position back to a storage position."
    },
    {
      "action_name": "auto-action_exposed_to_wait",
      "description": "将外部暴露位的微孔板送回等待位。",
      "description_en": "Return a microplate from the exposed position to the wait position."
    },
    {
      "action_name": "auto-action_read_barcode",
      "description": "读取指定存储位的条码信息。",
      "description_en": "Read barcode information from specified storage locations."
    },
    {
      "action_name": "auto-action_storage_to_exposed",
      "description": "将存储位微孔板移至外部暴露位。",
      "description_en": "Move a microplate from storage to the exposed external position."
    },
    {
      "action_name": "auto-action_storage_to_transfer",
      "description": "将存储位微孔板移至转运位。",
      "description_en": "Move a microplate from storage to the transfer station."
    },
    {
      "action_name": "auto-action_storage_to_wait",
      "description": "将存储位微孔板移至等待位。",
